style.css:
@-moz-document domain("open.spotify.com") {
html, body {
    background: url("https://i.imgur.com/8p8ZBTr.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #fff !important;
  }

  /* Make Spotify panels semi-transparent */
  .Root__now-playing-bar,
  .Root__top-bar,
  .Root__main-view,
  .main-view-container__scroll-node-child,
  .os-padding,
  .main-view-container,
  .main-rootlist-rootlist,
  .Root__left-sidebar,
  .Root__right-sidebar {
    background-color: rgba(0, 0, 0, 0.5) !important;
    backdrop-filter: blur(4px);
  }

  /* Optional: white text for visibility */
  .main-rootlist-rootlistItemLink,
  .main-navBar-navBarItemLink,
  .main-yourLibraryX-libraryTitle,
  .main-entityHeader-title,
  .main-entityHeader-subtitle {
    color: white !important;
  }

  /* Optional: remove Spotify gradient at top */
  .Root__top-bar::before {
    background: none !important;
  }
}
